function guardedOrFixture(){return phaseGraph([
 item(1,{oneOfInputs:[{artifact:'runtime-choice',consumerPhase:'candidate',alternatives:[
  {issue:2,artifact:'native.payload',producerPhase:'candidate'},
  {issue:3,artifact:'external.payload',producerPhase:'candidate',guards:[{issue:10,artifact:'sc01.decision',producerPhase:'accept',expectedScope:'scope-sc01.decision'}]}
 ],resolution:'Select one compatible payload and retain its branch guards'}]}),
 item(2,{outputs:[phaseOut(2,'native.payload','candidate')]}),
 item(3,{outputs:[phaseOut(3,'external.payload','candidate')]}),
 item(10,{outputs:[phaseOut(10,'sc01.decision','accept')]})
 ]);}
const selection=(group,r,guards=[])=>({group,consumerPhase:'candidate',compatible:true,compatibilityEvidence:'Exact selected payload compatibility',...r,guardBindings:guards.map(expectedFromReceipt)});
const preparedEvidence=()=>[{phase:'prepare',sourceRef:SHA,verified:true,evidence:'Preparation evidence',inputBindings:[],selectedInputs:[]}];
const candidateEvidence=(inputs=[],selected=[])=>[...preparedEvidence(),{phase:'candidate',sourceRef:SHA,verified:true,evidence:'Candidate evidence',inputBindings:inputs,selectedInputs:selected}];
const verifiedSourceInput=()=>[{id:'source',fromIssue:null,qualification:'reviewed source',sourceRef:SHA,digest:D,verified:true,evidence:'Source reviewed'}];
function projectionSnapshot(g,plans,receipts=[],kind='live'){
 return {snapshotKind:kind,observedAt:'2026-09-12T11:59:00Z',sourceRef:SHA,reviewedContext:true,
  frontiers:g.items.map(i=>{const p=plans[i.number]??{plannedPhase:'candidate'};return {issueNumber:i.number,issueUrl:`https://github.com/xrlab-dau/CHOOGuard/issues/${i.number}`,plannedPhase:p.plannedPhase,capturedStatus:{status:i.board.status,observedAt:'2026-09-12T11:00:00Z',sourceSnapshotCapturedAt:'2026-09-12T11:00:00Z',sourceIssueUpdatedAt:'2026-09-12T10:00:00Z',scope:'Captured GitHub Project status only'},phaseEvidence:p.phaseEvidence??preparedEvidence(),selectedInputs:p.selectedInputs??[],verifiedInputs:p.verifiedInputs??verifiedSourceInput(),verifiedSources:p.verifiedSources??[],sourceAccessEvidence:p.sourceAccessEvidence??[],predicateEvidence:p.predicateEvidence??[]};}),
  artifactReceipts:receipts,expectedArtifacts:receipts.map(expectedFromReceipt),resolvedAuthorities:[]};
}
