test('schema exposes strict optional relationship, qualifier, check-evidence and receipt-storage interfaces',()=>{
 const s=schema();
 assert.equal(s.$defs.relationshipDeclarations.additionalProperties,false);
 assert.equal(s.$defs.relationshipBlock.additionalProperties,false);assert.ok(s.$defs.relationshipBlock.required.includes('evaluatedPairs'));
 assert.equal(s.$defs.inputQualifier.additionalProperties,false);
 assert.equal(s.$defs.checkEvidence.additionalProperties,false);
 assert.equal(s.$defs.receiptStorage.oneOf.length,2);
 assert.ok(s.$defs.item.properties.relationshipDeclarations);
 assert.ok(s.$defs.item.properties.inputQualifiers);assert.ok(s.$defs.item.properties.checkEvidenceMappings);assert.equal(s.$defs.checkEvidenceMapping.oneOf.length,2);assert.ok(s.$defs.checkEvidenceMapping.oneOf.every(mapping=>mapping.additionalProperties===false));assert.ok(s.$defs.item.properties.generatedOutputClosure);assert.ok(s.$defs.phaseWriteScope.properties.childPolicy);assert.ok(s.$defs.check.properties.id);assert.equal(s.$defs.issue13Handoff.additionalProperties,false);
 assert.ok(s.$defs.check.properties.evidenceByPhase);assert.ok(s.$defs.check.properties.resultProtocol);assert.equal(s.$defs.checkResultProtocol.additionalProperties,false);
 assert.ok(s.$defs.artifactOutputBinding.properties.receiptStorage);
 assert.equal(s.$defs.accessOperation.properties.declaredAvailability.const,'local_unpublished');
 assert.equal(s.$defs.accessCaptureEvidence.additionalProperties,false);assert.equal(s.$defs.accessOperation.properties.captureEvidence.$ref,'#/$defs/accessCaptureEvidence');
});

test('compiler fails closed when R3 effective-record amendment provenance is absent, forged, or drifted',()=>{
 const g=round4IR(),sources=round4CompilerSources(),entry=structuredClone(workGraph.EFFECTIVE_RECORD_AMENDMENTS.amendments[0]);
 sources.effectiveRecordAmendments=[entry];assert.equal(workGraph.validateCompilerIR(g,sources).valid,false);
 g.effectiveRecordAmendments=[structuredClone(entry)];assert.equal(workGraph.validateCompilerIR(g,sources).valid,true);
 sources.effectiveRecordAmendments[0].previousReviewPacketSha256='c'.repeat(64);assert.equal(workGraph.validateCompilerIR(g,sources).valid,false);
 sources.effectiveRecordAmendments[0]=structuredClone(entry);sources.effectiveRecordAmendments[0].typo=true;assert.equal(workGraph.validateCompilerIR(g,sources).valid,false);
});

test('production renderer preserves optional qualifier, relationship, evidence, and receipt metadata visibly',()=>{
 const g=graph(),i=g.items[0],artifact=i.outputs[0].id,path=i.outputs[0].path,b=i.artifactOutputBindings.accept[0];
 i.inputQualifiers=[{inputId:'pm-method',qualification:'bounded exact authority',targets:[{artifact,phase:'accept',use:'Only this output.'}],notRequiredFor:['document-only work']}];
 i.relationshipDeclarations={parallel_with:{evaluatedPairs:[{issue:2,fromPhase:'candidate',toPhase:'candidate',reason:'Frozen static pair only.'}],items:[],reasonedNone:'No static parallel claim.'},conflicts_with:{evaluatedPairs:[{issue:2,fromPhase:'candidate',toPhase:'candidate',reason:'Frozen static pair only.'}],items:[],reasonedNone:'No captured exact conflict.'}};
 b.pathKind='immutable_receipt_index';b.rawReceiptPolicy='append-only';b.receiptStorage={mode:'embedded_append_only_index',appendOnly:true,completeRunRecordRequired:true};
 i.checks[0].evidenceByPhase={accept:{artifact,path}};i.checks[0].resultProtocol={states:['PASS','FAIL','NOT_RUN'],receiptFields:['artifactPath','artifactDigest','provenance','thresholdEvaluation','result','notRunReason'],notRunReasonRequiredWhen:'NOT_RUN'};
 const n=normalizeNodes(g)[0],packed=packGraph(g),html=renderReviewHtml(packed);
 assert.equal(n.inputQualifiers[0].targets[0].phase,'accept');assert.equal(n.relationshipDeclarations.parallel_with.items.length,0);assert.equal(packed.nodes[0].reviewStatus.state,'LEDGER_NOT_PROVIDED');
 for(const expected of ['Input qualifiers and bounded authority','Relationship declarations','No static parallel claim.','embedded_append_only_index','notRunReasonRequiredWhen','lifecycle is not projected'])assert.match(html,new RegExp(expected));assert.doesNotMatch(html,/Astra|검토 대기|draft_pending/);
});

